IMPORT_MODULES = ['aiohttp', 'anydoc', 'croniter', 'dateutil', 'distro', 'fire', 'nemo_relay', 'packaging', 'psutil', 'pytz', 'tqdm', 'watchfiles', 'websockets']
IMPORT_CHECK = r"(?<![\w.])(?:aiohttp|anydoc|croniter|dateutil|distro|fire|nemo_relay|packaging|psutil|pytz|tqdm|watchfiles|websockets)\."
IMPORT_STATEMENT = "import " + ", ".join(['aiohttp', 'anydoc', 'croniter', 'dateutil', 'distro', 'fire', 'nemo_relay', 'packaging', 'psutil', 'pytz', 'tqdm', 'watchfiles', 'websockets'])

UTIL_HELP = [
    "# utiltools — 5494 عنصراً عربياً",
]

_UTIL_TOKEN = re.compile(
    r"(?P<dot>\.)?"
    r"(?P<word>(?!\d)[\w\u064B-\u065F\u0670]+)"
    r"(?P<open>\s*\()?"
)

USER_NAMES = set()


def _util_replace(match):
    dot = match.group("dot")
    word = match.group("word")
    open_paren = match.group("open")
    if word in USER_NAMES:
        return match.group(0)
    if dot:
        if open_paren and word in UTIL_METHODS:
            return "." + UTIL_METHODS[word] + open_paren
        if word in UTIL_PROPS:
            return "." + UTIL_PROPS[word]
        return match.group(0)
    if word in UTIL_CONSTS:
        return UTIL_CONSTS[word]
    if word in UTIL_FUNCS:
        return UTIL_FUNCS[word] + (open_paren or "")
    return match.group(0)


def UTIL_SUBSTITUTE(text):
    """يترجم كلمات المكتبة في نص واحد ويُرجع المترجم."""
    if not text:
        return text
    return _UTIL_TOKEN.sub(_util_replace, text)
